    "nikolai_b": { "name": "Микола Остапович Бережний", "years": "нар. 1917", "place": "Заліман; згодом м. Цимлянськ", "role": "прадід, зенітник", "bio": "Народився в Залимані. На війні служив у 1342-му зенітному артилерійському полку, куди був призваний Балаклійським РВК. Згодом жив у Цимлянську Ростовської області. Чоловік Анастасії Порфирівни Бондаренко.", "facts": [ "Орден Вітчизняної війни II ступеня (ювілейне нагородження 1985 р.).", "Джерело: «Память народа». Особу підтвердила мама упорядника." ] },

    "anastasia": { "name": "Анастасія Порфирівна Бондаренко", "years": "нар. 13.04.1918", "place": "Заліман", "role": "прабабуся", "bio": "Донька георгіївського кавалера Порфирія Бондаренка. Народилася й охрещена 13 квітня 1918 року в Залимані. Вийшла заміж за Миколу Остаповича Бережного.", "facts": [ "Метричний запис № 16: ДАХО 40-139-372.", "Донька — Анна Миколаївна Бережна." ] },
    "twin_andrey": { "name": "Андрій Порфирович Бондаренко", "years": "30.11 – груд. 1919", "place": "Заліман", "role": "близнюк, помер немовлям", "bio": "Народився 30 листопада 1919 року разом із братом Афанасієм і прожив два дні.", "facts": [ "Запис про народження № 62–63 і запис про смерть: ДАХО 40-139-372." ] },
    "twin_afanasy": { "name": "Афанасій Порфирович Бондаренко", "years": "нар. 30.11.1919", "place": "Заліман", "role": "близнюк", "bio": "Народився 30 листопада 1919 року разом із братом Андрієм. Подальша доля невідома.", "facts": [ "Запис про народження № 62–63: ДАХО 40-139-372." ] },
    "daniil_b": { "name": "Данило Порфирович Бондаренко", "years": "нар. 21.12.1921", "place": "Заліман", "role": "полковник, двоюрідний прадід", "bio": "Син Порфирія Бондаренка, кадровий офіцер. Пройшов радянсько-фінську та Другу світову війни, службу завершив полковником.", "facts": [ "Призваний 09.12.1939; учасник радянсько-фінської війни 1939–1940.", "81-й стрілецький полк 54-ї сд, Кемська оперативна група Карельського фронту.", "Майор, старший помічник начальника відділення з використання досвіду війни оперативного відділу штабу 26-ї армії.", "Лейтенант → старший лейтенант → капітан → майор → полковник.", "Ордени Вітчизняної війни II та I ступенів, медаль «За перемогу над Німеччиною».", { "t": "Служив у Києві, був знайомий із Фіделем Кастро й подарував йому двох папуг.", "s": "family" } ] },
    "evgeny": { "name": "Євген Данилович Бондаренко", "place": "Харків", "role": "начальник цивільної оборони", "bio": "Син Данила Порфировича. Зі слів родини, був начальником цивільної оборони Харкова та Харківської області." },
    "zinaida": { "name": "Зінаїда Бондаренко", "role": "донька Данила Порфировича" },

    "porfiry": { "name": "Порфирій Власович Бондаренко", "years": "згад. 1916–1919", "place": "с. Заліман, Савинська волость", "role": "прапрадід, георгіївський кавалер", "bio": "Гренадер 12-го гренадерського Астраханського Імператора Олександра III полку, православний, одружений, родом із села Заліман Ізюмського повіту Харківської губернії. У вересні 1916 року був поранений біля села Затурці на Волині, а в листопаді отримав Георгіївський хрест IV ступеня № 734616.", "facts": [ "Поранений 21.09.1916 біля с. Затурці; евакуйований через перев'язувальний загін Московських біржового та купецького товариств.", "Георгіївський хрест IV ступеня № 734616 наданий 16.11.1916 на огляді.", { "t": "Хрест вручив Великий Князь Георгій Михайлович:", "q": "от Имени Государя Императора", "tr": "від Імені Государя Імператора" }, "Запис про нагороду є також у С. Б. Патрікеєва: «Сводные списки кавалеров Георгиевского креста 1914–1922», т. 11.", { "t": "Переказ: «золотий хрест, дав сам цар»; був кульгавим або без ноги. Хрест IV ступеня був срібним, а вручав його член імператорської родини від імені царя — тож переказ майже точний.", "s": "family" } ] },
    "maria": { "name": "Марія Симеонівна Бондаренко", "place": "Заліман", "role": "прапрабабуся", "bio": "Дружина Порфирія Власовича, мати Анастасії, Андрія, Афанасія та Данила." },
    "ksenia": { "name": "Ксенія Власівна Бондаренко", "years": "нар. 27.01.1903", "place": "Заліман", "role": "донька Власа Савелійовича", "facts": [ "Метричний запис № 7: ДАХО ф. 40 оп. 139 спр. 228." ] },
    "matrona_v": { "name": "Матрона Власівна Бондаренко", "years": "згад. 1919", "place": "Заліман", "role": "донька Власа Савелійовича", "bio": "Згадана хрещеною в записі 1919 року.", "facts": [ { "t": "Запис у метричній книзі:", "q": "Власа Савелиева дочь девица Матрона", "tr": "Власа Савелієва донька дівиця Матрона" } ] },
    "vlas": { "name": "Влас Савелійович Бондаренко", "years": "згад. 1903", "place": "Заліман", "role": "прапрапрадід, солдат запасу", "bio": "Батько георгіївського кавалера. У метричній книзі 1903 року записаний рядовим, тобто солдатом запасу.", "facts": [ { "t": "Запис 1903 р.:", "q": "села Залимана рядовой", "tr": "села Залимана рядовий" }, "Дружина — Дар'я Федорівна. Брат — Євграф Савелійович, теж рядовий.", "Народження доньки Ксенії: запис № 7, 27.01.1903, ДАХО ф. 40 оп. 139 спр. 228." ] },
