    "estate_quote": { "q": "слободы Залимана крестьяне", "tr": "слободи Заліман селяни" },
    "dynasty_title": "Сила роду — служба",
    "dynasty": [ { "k": "1916", "v": "Гренадер, георгіївський кавалер" }, { "k": "1939–", "v": "Кадровий офіцер, полковник" }, { "k": "Далі", "v": "Начальник цивільної оборони" } ]
