  "stories": {
    "porfiry": {
      "kicker": "Ausstellung I", "title": "Porfyrij Bondarenko", "subtitle": "Georgsritter aus dem Dorf Saliman",
      "plaque": [ { "k": "Auszeichnung", "v": "Georgskreuz IV. Klasse" }, { "k": "Nummer", "v": "Nr. 734616" }, { "k": "Verliehen", "v": "16.11.1916" } ],
      "sections": [
        { "year": "1903", "heading": "Sohn eines Reservisten", "text": "Das Kirchenbuch von Saliman nennt seinen Vater Wlas Saweljewitsch einen Gemeinen. Der Dienst gehörte schon zum Leben dieser Familie: Auch Porfyrijs Onkel Jewgraf ist als Gemeiner verzeichnet.", "quote": { "q": "села Залимана рядовой", "tr": "Gemeiner aus dem Dorf Saliman" }, "doc": "vlas_1903" },
        { "year": "1916", "heading": "Grenadier des Astrachaner Regiments", "text": "Porfyrij dient im 12. Astrachaner Grenadierregiment Kaiser Alexanders III. Die Akten beschreiben ihn knapp: orthodox, verheiratet, Gouvernement Charkow, Kreis Isjum, Wolost Sawinzy, Dorf Saliman." },
        { "year": "21.09.1916", "heading": "Verwundet bei Saturzy", "text": "In Wolhynien, beim Dorf Saturzy, wird der Grenadier verwundet. Er wird über die Verbandsstelle der Moskauer Börsen- und Kaufmannsgesellschaften evakuiert; davon zeugt eine Karte des Verlustbüros.", "doc": "porfiry_ranenie" },
        { "year": "16.11.1916", "heading": "Kreuz Nr. 734616", "text": "Als besonders Ausgezeichneter erhält Porfyrij bei einer Truppenschau das Georgskreuz IV. Klasse. Überreicht wird es von Großfürst Georgi Michailowitsch. Die Verleihung ist in der Regimentsliste und in den Sammellisten von S. B. Patrikejew erhalten.", "quote": { "q": "от Имени Государя Императора", "tr": "im Namen Seiner Majestät des Kaisers" }, "doc": "porfiry_nagrada" },
        { "year": "Überlieferung", "kind": "legend", "heading": "„Ein goldenes Kreuz, vom Zaren selbst“", "text": "In der Familie hieß es, das Kreuz sei aus Gold gewesen und vom Zaren selbst gekommen, und Porfyrij habe gehinkt oder ein Bein verloren. Das Kreuz IV. Klasse war aus Silber, doch überreicht wurde es tatsächlich von einem Mitglied des Kaiserhauses im Namen des Zaren. Die Erinnerung der Familie war fast genau." },
        { "year": "1918–1921", "heading": "Zu Hause in Saliman", "text": "Mit Marija Simeonowna zieht er in seinem Heimatdorf die Kinder groß. 1918 wird Anastassija geboren, 1919 die Zwillinge Andrej und Afanassi; Andrej stirbt zwei Tage alt. 1921 kommt Daniil zur Welt, der spätere Oberst.", "doc": "anastasia_1918" }
      ],
      "family": [ "maria", "anastasia", "twin_andrey", "twin_afanasy", "daniil_b", "vlas" ]
    },
    "daniil": {
      "kicker": "Ausstellung II", "title": "Daniil Bondarenko", "subtitle": "Oberst, Sohn eines Georgsritters",
      "photo": "daniil_foto",
      "plaque": [ { "k": "Geboren", "v": "21.12.1921, Saliman" }, { "k": "Im Dienst", "v": "seit 9.12.1939" }, { "k": "Rang", "v": "Oberst" } ],
      "ladder_title": "Der Weg durch die Ränge", "ladder": [ "Leutnant", "Oberleutnant", "Hauptmann", "Major", "Oberst" ],
      "sections": [
        { "year": "1939–1940", "heading": "Der erste Krieg", "text": "Am 9. Dezember 1939, kurz vor seinem achtzehnten Geburtstag, wird der Sohn des Georgsritters einberufen und nimmt am sowjetisch-finnischen Krieg teil." },
        { "year": "Bis 1944", "heading": "Die Karelische Front", "text": "81. Schützenregiment der 54. Schützendivision, dann die Operative Gruppe Kem der Karelischen Front. 1944 ist er Major und Erster Gehilfe des Leiters der Abteilung für die Auswertung der Kriegserfahrung in der Operationsabteilung im Stab der 26. Armee." },
        { "year": "9.10.1944", "heading": "Das Auszeichnungsblatt", "text": "Orden des Vaterländischen Krieges II. Klasse. Mit einer Funkstation bei Einheiten der 205. Schützendivision sicherte er dem Armeeoberbefehlshaber die Truppenführung bei der Verfolgung des Gegners in Richtung Kestenga; außerdem war er operativer Diensthabender und wertete Kampferfahrungen aus.", "doc": "daniil_nagradnoy" },
        { "year": "Auszeichnungen", "heading": "Zwei Orden und eine Medaille", "text": "Orden des Vaterländischen Krieges II. Klasse, Orden des Vaterländischen Krieges I. Klasse und die Medaille „Für den Sieg über Deutschland“." },
        { "year": "Überlieferung", "kind": "legend", "heading": "Zwei Papageien für Fidel", "text": "In der Familie erzählt man, Daniil habe in Kyjiw gedient, Fidel Castro gekannt und ihm zwei Papageien geschenkt. Castro war tatsächlich im Mai 1963 und im Januar 1964 in Kyjiw; die Begegnung selbst ist noch nicht dokumentiert." },
        { "year": "Nachkommen", "heading": "Die Linie des Dienstes geht weiter", "text": "Nach Angaben der Familie wurde sein Sohn Jewgeni Leiter des Zivilschutzes von Charkiw und des Gebiets Charkiw. Ein Grenadier von 1916, ein Oberst, ein Leiter des Zivilschutzes: drei Generationen im Dienst." }
      ],
      "family": [ "porfiry", "anastasia", "evgeny", "zinaida" ]
    }
  },
  "zaliman": {
    "title": "Saliman", "subtitle": "Die Heimat der Familie am Siwerskyj Donez",
    "facts": [ { "k": "Gegründet", "v": "um 1671" }, { "k": "Bewohner", "v": "Staatsbauern" }, { "k": "Kreis", "v": "Isjum, Gouvernement Charkow" }, { "k": "Wolost", "v": "Sawinzy" } ],
    "paragraphs": [
      "Saliman wurde um 1671 am Ufer des Siwerskyj Donez gegenüber von Sawinzy gegründet. Seine Bewohner waren Staatsbauern des Kreises Isjum im Gouvernement Charkow.",
      "Später gehörte das Dorf zum Rajon Balaklija und dann zum Rajon Isjum im Gebiet Charkiw. In denselben Kirchenbüchern stehen hier die Narozhnyis, Bereschnois und Bondarenkos nebeneinander."
    ],
    "estate_title": "Stand",
    "estate_text": "In Dokumenten von 1903 sind die Einwohner von Saliman Staatsbauern, 1918–1919 Bauern der Sloboda Saliman. Adlige Wurzeln wurden nicht festgestellt.",
    "estate_quote": { "q": "слободы Залимана крестьяне", "tr": "Bauern der Sloboda Saliman" },
    "dynasty_title": "Die Stärke der Familie ist der Dienst",
    "dynasty": [ { "k": "1916", "v": "Grenadier, Georgsritter" }, { "k": "1939–", "v": "Berufsoffizier, Oberst" }, { "k": "Später", "v": "Leiter des Zivilschutzes" } ]
  },
